package org.millenaire.common.village;import java.util.*;import org.millenaire.common.item.*;import org.millenaire.common.utilities.*;public class Building{public int seeds;public static class Resources{public List<Point> soils=new ArrayList<>();public List<Point> getSoilPoints(net.minecraft.resources.ResourceLocation id){return soils;}}public Resources resources=new Resources();public Resources getResManager(){return resources;}public int countGoods(InvItem i){return seeds;}public int takeGoods(InvItem i,int n){int taken=Math.min(seeds,n);seeds-=taken;return taken;}}